The evidence points to one root cause: product-catalog went down at about 03:18:46 and stayed down. Its failure reached the user-facing frontend through checkout and recommendation.

```json
{
  "root_causes": [
    {
      "service": "product-catalog",
      "fault_kind": "pod_unavailable",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT 'abn' AS p, count(*) AS n FROM abnormal_traces WHERE service_name='product-catalog' UNION ALL SELECT 'nor', count(*) FROM normal_traces WHERE service_name='product-catalog'",
          "claim": "Product-catalog has zero spans in the incident window versus 285 server spans in the normal period."
        },
        {
          "kind": "log",
          "sql": "SELECT service_name, level, time FROM abnormal_logs WHERE service_name='product-catalog' ORDER BY time",
          "claim": "Product-catalog logs stop after startup at about 03:18:42 and never resume during the incident window."
        },
        {
          "kind": "metric",
          "sql": "SELECT 'abn' AS p, metric, avg(value) AS avg_v, min(time) AS t0, max(time) AS t1 FROM abnormal_metrics WHERE service_name='product-catalog' AND metric IN ('container.cpu.usage','container.memory.usage','container.memory.rss') GROUP BY ALL UNION ALL SELECT 'nor', metric, avg(value), min(time), max(time) FROM normal_metrics WHERE service_name='product-catalog' AND metric IN ('container.cpu.usage','container.memory.usage','container.memory.rss') GROUP BY ALL",
          "claim": "Product-catalog container CPU, memory usage and RSS collapse to near zero from 03:18:46 onward, versus steady normal levels."
        },
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_status_code, count(*) AS n, quantile_cont(duration,0.5)/1e6 AS p50_ms FROM abnormal_traces WHERE span_name IN ('oteldemo.ProductCatalogService/GetProduct','/oteldemo.ProductCatalogService/ListProducts','grpc.oteldemo.ProductCatalogService/GetProduct') GROUP BY ALL ORDER BY 1,2",
          "claim": "Every call to product-catalog from checkout, recommendation and frontend ends in Error status, failing fast."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "product-catalog",
      "to": "recommendation",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, attr_status_code, count(*) AS n FROM abnormal_traces WHERE service_name='recommendation' GROUP BY ALL ORDER BY 2,3",
          "claim": "Recommendation's client calls to product-catalog (ListProducts) all error, and its internal get_product_list span errors too."
        }
      ]
    },
    {
      "from": "product-catalog",
      "to": "checkout",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, attr_status_code, count(*) AS n FROM abnormal_traces WHERE service_name='checkout' AND span_name LIKE '%ProductCatalog%' GROUP BY ALL",
          "claim": "Checkout's GetProduct calls to product-catalog all return Error, and its PlaceOrder server spans all fail."
        }
      ]
    },
    {
      "from": "product-catalog",
      "to": "frontend",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT span_name, attr_status_code, count(*) AS n FROM abnormal_traces WHERE service_name='frontend' AND span_name IN ('grpc.oteldemo.ProductCatalogService/GetProduct','tcp.connect') GROUP BY ALL",
          "claim": "Frontend's product-catalog GetProduct calls fail (88 errors), and tcp.connect errors appear (13) where normal has none."
        }
      ]
    },
    {
      "from": "recommendation",
      "to": "frontend",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT span_name, attr_status_code, attr_http_response_status_code, count(*) AS n FROM abnormal_traces WHERE service_name='frontend' AND span_name IN ('grpc.oteldemo.RecommendationService/ListRecommendations','GET /api/recommendations') GROUP BY ALL",
          "claim": "Frontend's ListRecommendations calls and /api/recommendations requests all fail with HTTP 500 in the incident window."
        }
      ]
    },
    {
      "from": "checkout",
      "to": "frontend",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT span_name, attr_status_code, attr_http_response_status_code, count(*) AS n FROM abnormal_traces WHERE service_name='frontend' AND span_name IN ('grpc.oteldemo.CheckoutService/PlaceOrder','POST /api/checkout') GROUP BY ALL",
          "claim": "Frontend's PlaceOrder calls and POST /api/checkout requests fail with HTTP 500 after checkout's PlaceOrder errors."
        }
      ]
    },
    {
      "from": "frontend",
      "to": "frontend-proxy",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, count(*) AS n, avg(CASE WHEN attr_status_code='Error' THEN 1.0 ELSE 0 END) AS err_share FROM abnormal_traces WHERE service_name='frontend-proxy' AND attr_span_kind='Server' GROUP BY ALL",
          "claim": "Frontend-proxy server spans show about 62% errors in the incident window, up from about 10% in normal."
        }
      ]
    }
  ]
}
```

